def _triangular_coordinate(self, index, *, loc=None, ip=None):
    root = cutlass.Float32(cute.math.sqrt(cutlass.Float32(index * 8 + 1)))
    row = ((root - 1.0) * 0.5).to(cutlass.Int32)
