def custom_kernel(data: input_t) -> output_t:
    global _active_shape, _info, _workspace
    n = data.shape[-1]
    if n == 32:
        return _ext.cholesky32_cuda(data)
    if n == 64:
        return _ext.cholesky64_cuda(data)
    if n == 128:
        return _ext.cholesky128_cuda(data)
    if n >= 32:
        use_mixed = (
            n >= 8192
            or (n >= 4096 and data.shape[0] == 1)
            or (n >= 1024 and data.shape[0] >= 16)
        )
        shape = tuple(data.shape)
        if shape != _active_shape:
            _output_cache.clear()
            _active_shape = shape
            if use_mixed:
                _info = None
                _workspace = None
            else:
                _info = torch.empty(
                    data.shape[0], device=data.device, dtype=torch.int32
                )
                use_looped = data.shape[0] <= 4 and n >= 1024
                if use_looped:
                    lwork = _ext.workspace_size(data)
                    _workspace = torch.empty(
                        lwork, device=data.device, dtype=torch.float32
                    )
                else:
                    _workspace = torch.empty(
                        0, device=data.device, dtype=torch.float32
                    )
        key = id(data)
        entry = _output_cache.get(key)
        if entry is None or entry[0] is not data:
            output = torch.empty_like(data, memory_format=torch.contiguous_format)
            use_looped = data.shape[0] <= 4 and n >= 1024
            if not use_mixed and not use_looped:
                step = n * n * data.element_size()
                pointers = torch.arange(
                    output.data_ptr(),
                    output.data_ptr() + data.shape[0] * step,
                    step,
                    device=data.device,
                    dtype=torch.int64,
                )
            else:
                pointers = torch.empty(0, device=data.device, dtype=torch.int64)
            _output_cache[key] = (data, output, pointers)
        else:
            output, pointers = entry[1], entry[2]
        if use_mixed:
            return _blocked_cholesky(data, output)
        return _ext.direct_cholesky(data, output, pointers, _info, _workspace)
    return torch.linalg.cholesky_ex(data, check_errors=False).L
